mapper.select:
SELECT * FROM workflow_variables 
WHERE scope = #{scope} 
  AND user_id = #{userId} 
  AND deleted = false
ORDER BY created_at DESC

mapper.update:
UPDATE workflow_variables 
SET deleted = true, updated_at = NOW() 
WHERE scope = #{scope} 
  AND user_id = #{userId} 
  AND deleted = false

mapper.select:
SELECT COUNT(*) FROM workflow_variables 
WHERE user_id = #{userId} 
  AND deleted = false

mapper.delete:
DELETE FROM workflow_variables 
WHERE expires_at IS NOT NULL 
  AND expires_at < #{expireTime}
